/* geometry.h */
#ifndef CODESAATHI_GEOMETRY_H
#define CODESAATHI_GEOMETRY_H

double rectangle_area(double width, double height);

#endif

/* geometry.c */
#include "geometry.h"

double rectangle_area(double width, double height)
{
    return width * height;
}

/* main.c */
#include <stdio.h>
#include "geometry.h"

int main(void)
{
    printf("area=%.2f\n", rectangle_area(3.0, 4.0));
    return 0;
}

/* counter.h */
#ifndef CODESAATHI_COUNTER_H
#define CODESAATHI_COUNTER_H

typedef struct {
    unsigned int value;
} Counter;

void counter_increment(Counter *counter);

#endif

/* counter.c */
#include <stddef.h>
#include "counter.h"

void counter_increment(Counter *counter)
{
    if (counter != NULL) {
        ++counter->value;
    }
}
